def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    v3 = vars["v3"]
    lowest = min(v1, v2, v3)
    return {
        "value": lowest,
        "trace": {
            "v1": v1,
            "v2": v2,
            "v3": v3,
            "comparison": "minimum",
            "output_meta": {
                "currency": "USD",
                "scale": "billion",
                "unit": None
            }
        }
    }
